import { expect, test } from './fixtures';

/*
 * IMPORT A BACKUP's pick screen against its board (c438; doc/IMPORT-BACKUP.md). The
 * board is drawn at a 1440-wide desktop, beside the sidebar, so this runs in
 * the desktop project alone: every other project ignores it
 * (playwright.config.ts's DESKTOP_ONLY, c510), so it neither lists nor skips
 * anywhere else. It only reads /import, which writes nothing, so it runs on
 * the shared seed.
 */
test.use({ viewport: { width: 1440, height: 2400 } });

/**
 * Import-Pick (00 — CHOOSE THE FILE), in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: /home/masshiro/work/tsundoku/wave20/import/doc/handoffs/import-backup/Import-Pick.dc.html
 * Extracted at 2026-11-04T11:59:00.746Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	region2: '.imp header .cell.left .cellx',
	region3: '.imp header .bar-title',
	region5: '.imp section.pg .drop',
	region6: '.imp section.pg .drop .btn',
	region7: '.imp section.pg .lab',
	region8: ':nth-match(.imp section.pg .blk .r .tx, 1)',
	region9: ':nth-match(.imp section.pg .blk .r .tx, 2)',
	region10: ':nth-match(.imp section.pg .blk .r .tx, 3)',
	region11: '.imp section.pg .two',
	region12: ':nth-match(.imp section.pg .two > div, 1)',
	region13: ':nth-match(.imp section.pg .two > div, 2)'
};

test('Import-Pick (00 — CHOOSE THE FILE): region2 matches the handoff', async ({ page }) => {
	await page.goto(`${base}/import`);
	await expect(page.locator(SEL.region2)).toBeVisible();

	const region2Style = await page.locator(SEL.region2).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingRight: cs.paddingRight,
			paddingLeft: cs.paddingLeft,
			borderRightWidth: cs.borderRightWidth,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight
		};
	});
	expect(region2Style.display).toBe('flex');
	expect(region2Style.alignItems).toBe('center');
	expect(region2Style.rowGap).toBe('12px');
	expect(region2Style.columnGap).toBe('12px');
	expect(region2Style.paddingRight).toBe('24px');
	expect(region2Style.paddingLeft).toBe('24px');
	expect(region2Style.borderRightWidth).toBe('1px');
	expect(region2Style.fontSize).toBe('14px');
	expect(region2Style.fontWeight).toBe('500');
});

